#!/bin/bash\n\n# smg4OS System Information\n# \"Let me take a look at what you're working with here...\"\n\nset -e\n\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\nWIZARD_DIR=\"$(dirname \"$SCRIPT_DIR\")\"\n\nsource \"$WIZARD_DIR/scripts/colors.sh\"\n\nsmg4_say \"Let me scan your system... *beep boop*\"\nsleep 1\n\necho \"\"\necho -e \"${BLUE}════════════════════════════════════════════════════════════════${NC}\"\necho -e \"${BLUE}  SYSTEM INFORMATION${NC}\"\necho -e \"${BLUE}════════════════════════════════════════════════════════════════${NC}\"\necho \"\"\n\necho -e \"${GOLD}OS Information:${NC}\"\nif [ -f /etc/os-release ]; then\n    . /etc/os-release\n    echo \"  Distribution: $PRETTY_NAME\"\nelse\n    echo \"  Could not determine OS\"\nfi\necho \"  Kernel: $(uname -r)\"\necho \"  Architecture: $(uname -m)\"\n\necho \"\"\necho -e \"${GOLD}Hardware:${NC}\"\necho \"  Processor: $(grep -m1 'model name' /proc/cpuinfo | cut -d':' -f2 | xargs)\"\necho \"  CPU Cores: $(nproc)\"\necho \"  Memory: $(free -h | grep Mem | awk '{print $2}')\"\necho \"  Storage: $(df -h / | tail -1 | awk '{print $2}')\"\n\necho \"\"\necho -e \"${GOLD}Desktop Environment:${NC}\"\nif command -v xfce4-about &>/dev/null; then\n    echo \"  Detected: XFCE4\"\nelif command -v openbox &>/dev/null; then\n    echo \"  Detected: Openbox\"\nelif command -v gnome-shell &>/dev/null; then\n    echo \"  Detected: GNOME\"\nelse\n    echo \"  Detected: None (Headless or unknown)\"\nfi\n\necho \"\"\necho -e \"${GOLD}Display:${NC}\"\nif [ -n \"$DISPLAY\" ]; then\n    echo \"  X11 Display: $DISPLAY\"\nelse\n    echo \"  No X11 display detected\"\nfi\n\necho \"\"\necho -e \"${GOLD}User Information:${NC}\"\necho \"  Current User: $USER\"\necho \"  Home: $HOME\"\necho \"  Shell: $SHELL\"\n\necho \"\"\necho -e \"${GOLD}Development Tools:${NC}\"\ncommand -v gcc &>/dev/null && echo \"  GCC: $(gcc --version | head -1 | cut -d' ' -f3)\" || echo \"  GCC: Not installed\"\ncommand -v python3 &>/dev/null && echo \"  Python: $(python3 --version | cut -d' ' -f2)\" || echo \"  Python: Not installed\"\ncommand -v git &>/dev/null && echo \"  Git: $(git --version | cut -d' ' -f3)\" || echo \"  Git: Not installed\"\ncommand -v node &>/dev/null && echo \"  Node.js: $(node --version)\" || echo \"  Node.js: Not installed\"\ncommand -v docker &>/dev/null && echo \"  Docker: $(docker --version | cut -d' ' -f3)\" || echo \"  Docker: Not installed\"\n\necho \"\"\necho -e \"${GOLD}Network:${NC}\"\nhostname_val=$(hostname)\necho \"  Hostname: $hostname_val\"\nif command -v ip &>/dev/null; then\n    ip_addr=$(ip route get 1 2>/dev/null | awk '{print $NF;exit}')\n    if [ -n \"$ip_addr\" ]; then\n        echo \"  IP Address: $ip_addr\"\n    fi\nfi\n\necho \"\"\necho -e \"${BLUE}════════════════════════════════════════════════════════════════${NC}\"\necho \"\"\n\nsmg4_say \"Well, that's your system! Looks pretty good to me!\"\necho \"\"\n"